   357→		}
   358→
   359→		// Check for checkpoint trailer
   360→		checkpointID, found := paths.ParseCheckpointTrailer(c.Message)
   361→		if !found {
   362→			return nil
   363→		}
   364→
   365→		// Skip if already seen
   366→		if seenCheckpoints[checkpointID] {
   367→			return nil
   368→		}
   369→		seenCheckpoints[checkpointID] = true
   370→
   371→		// Get checkpoint info from map
   372→		cpInfo, ok := checkpointInfoMap[checkpointID]
   373→		if !ok {
   374→			// Checkpoint exists in commit but not in entire/sessions (may have been pruned)
   375→			return nil
   376→		}
   377→
   378→		// Extract first line of commit message for display
   379→		commitMsg := c.Message
   380→		if idx := strings.Index(commitMsg, "\n"); idx != -1 {
   381→			commitMsg = commitMsg[:idx]
   382→		}
