   412→// findBranchesAndCommitsForCheckpoint finds branches that contain a commit with this checkpoint ID.
   413→// Returns a map of branch name -> commit info. Only searches commits unique to each branch (not reachable from main).
   414→func findBranchesAndCommitsForCheckpoint(repo *git.Repository, checkpointID string, mainBranch string, mainCommits map[plumbing.Hash]bool) map[string]commitInfo {
   415→	result := make(map[string]commitInfo)
   416→
   417→	// Get all local branches
   418→	refs, err := repo.References()
   419→	if err != nil {
   420→		return result
   421→	}
   422→
   423→	_ = refs.ForEach(func(ref *plumbing.Reference) error { //nolint:errcheck // Best-effort search
   424→		if !ref.Name().IsBranch() {
   425→			return nil
   426→		}
   427→
   428→		// Skip shadow branches
   429→		branchName := ref.Name().Short()
   430→		if strings.HasPrefix(branchName, "entire/") {
   431→			return nil
   432→		}
   433→
   434→		// Skip main branch itself (it gets added separately)
   435→		if branchName == mainBranch {
   436→			return nil
   437→		}
   438→
   439→		// Search commits unique to this branch
   440→		iter, err := repo.Log(&git.LogOptions{From: ref.Hash()})
   441→		if err != nil {
   442→			return nil //nolint:nilerr // Continue to next branch on error
   443→		}
   444→
   445→		count := 0
   446→		_ = iter.ForEach(func(c *object.Commit) error { //nolint:errcheck // Best-effort search, errors are intentional stops
   447→			count++
   448→			if count > maxCommitsToScanPerBranch {
   449→				return errors.New("limit reached")
   450→			}
   451→
   452→			// Skip commits that are reachable from main (shared commits)
   453→			if mainCommits != nil && mainCommits[c.Hash] {
   454→				return nil
   455→			}
   456→
   457→			cpID, hasTrailer := paths.ParseCheckpointTrailer(c.Message)
   458→			if hasTrailer && cpID == checkpointID {
   459→				// Extract first line of commit message
   460→				commitMsg := c.Message
   461→				if idx := strings.Index(commitMsg, "\n"); idx != -1 {
   462→					commitMsg = commitMsg[:idx]
   463→				}
   464→				// Get diff stats
   465→				insertions, deletions := getCommitDiffStats(repo, c)
   466→				result[branchName] = commitInfo{
   467→					Hash:       c.Hash.String()[:7],
   468→					Message:    commitMsg,
   469→					Author:     c.Author.Name,
   470→					Insertions: insertions,
   471→					Deletions:  deletions,
   472→				}
