   489→// buildSessionsForCheckpoint creates SessionInfo entries for all sessions in a checkpoint.
   490→// Sessions are kept in the order they appear in the session_ids array from metadata.
   491→func buildSessionsForCheckpoint(repo *git.Repository, cpInfo strategy.CheckpointInfo, checkpointID string, isSessionActive func(string) bool, _ map[string]*session.State) []SessionInfo {
   492→	sessionIDs := cpInfo.GetSessionIDs()
   493→
   494→	// Calculate per-session step count (estimate: divide evenly among sessions)
   495→	totalSteps := cpInfo.GetStepsCount()
   496→	sessionCount := len(sessionIDs)
   497→	if sessionCount == 0 {
   498→		sessionCount = 1
   499→	}
   500→	perSessionSteps := totalSteps / sessionCount
   501→
   502→	sessions := make([]SessionInfo, 0, len(sessionIDs))
   503→	for i, sessionID := range sessionIDs {
   504→		// For the first (newest) session, get description from root
   505→		// For older sessions, use a placeholder
   506→		var description string
   507→		if i == 0 {
   508→			description = getDescriptionForCheckpoint(repo, checkpointID)
   509→		} else {
   510→			description = "Archived session"
   511→		}
   512→
   513→		sessions = append(sessions, SessionInfo{
   514→			SessionID:   sessionID,
   515→			Description: description,
   516→			IsActive:    isSessionActive(sessionID),
   517→			Agent:       cpInfo.Agent,
   518→			StepsCount:  perSessionSteps,
   519→		})
   520→	}
   521→
   522→	return sessions
   523→}
