   609→
   610→// getCommitDiffStatsFiltered computes diff stats, optionally excluding paths matching a prefix.
   611→// Returns (insertions, deletions, fileCount).
   612→func getCommitDiffStatsFiltered(c *object.Commit, excludePrefixes []string) (insertions, deletions int) {
   613→	// Get parent tree (empty tree for initial commits)
   614→	var parentTree *object.Tree
   615→	if c.NumParents() > 0 {
   616→		parent, err := c.Parent(0)
   617→		if err == nil {
   618→			parentTree, err = parent.Tree()
   619→			if err != nil {
   620→				return 0, 0
   621→			}
   622→		}
   623→	}
   624→
   625→	// Get current tree
   626→	currentTree, err := c.Tree()
   627→	if err != nil {
   628→		return 0, 0
   629→	}
   630→
   631→	// Compute diff
   632→	changes, err := parentTree.Diff(currentTree)
   633→	if err != nil {
   634→		return 0, 0
   635→	}
   636→
   637→	// Sum up stats from all changes
   638→	for _, change := range changes {
   639→		patch, err := change.Patch()
   640→		if err != nil {
   641→			continue
   642→		}
   643→		for _, fileStat := range patch.Stats() {
   644→			// Check if file should be excluded
   645→			excluded := false
   646→			for _, prefix := range excludePrefixes {
   647→				if strings.HasPrefix(fileStat.Name, prefix) {
   648→					excluded = true
   649→					break
   650→				}
   651→			}
   652→			if excluded {
   653→				continue
   654→			}
   655→			insertions += fileStat.Addition
   656→			deletions += fileStat.Deletion
   657→		}
   658→	}
   659→
   660→	return insertions, deletions
   661→}
