   663→// fetchUncommittedCheckpoints retrieves shadow branch checkpoints that haven't been committed yet.
   664→// Only works when manual-commit strategy is active.
   665→// Task checkpoints are nested under their parent prompt checkpoint.
   666→func fetchUncommittedCheckpoints(committedCheckpoints map[string]strategy.CheckpointInfo, isSessionActive func(string) bool) []CheckpointInfo {
   667→	// Get current strategy
   668→	strat := GetStrategy()
   669→	if strat == nil {
   670→		return nil
   671→	}
   672→
   673→	// Only manual-commit strategy has shadow branch checkpoints
   674→	if strat.Name() != "manual-commit" {
   675→		return nil
   676→	}
   677→
   678→	// Get rewind points from the strategy (includes uncommitted shadow branch checkpoints)
   679→	rewindPoints, err := strat.GetRewindPoints(50)
   680→	if err != nil {
   681→		return nil
   682→	}
   683→
   684→	// Build set of committed checkpoint IDs to avoid duplicates
   685→	committedIDs := make(map[string]bool)
   686→	for cpID := range committedCheckpoints {
   687→		committedIDs[cpID] = true
   688→	}
   689→
   690→	// First pass: separate prompt checkpoints and task checkpoints
   691→	// Task checkpoints will be nested under their parent prompt checkpoint
   692→	var promptCheckpoints []CheckpointInfo
   693→	var taskCheckpoints []CheckpointInfo
   694→
   695→	for _, point := range rewindPoints {
   696→		// Skip logs-only points (these are already committed)
   697→		if point.IsLogsOnly {
   698→			continue
   699→		}
   700→
   701→		// Skip if this checkpoint ID is already in the committed list
   702→		if point.CheckpointID != "" && committedIDs[point.CheckpointID] {
   703→			continue
   704→		}
   705→
   706→		// This is an uncommitted shadow branch checkpoint
   707→		shortHash := point.ID
   708→		if len(shortHash) > 7 {
   709→			shortHash = shortHash[:7]
   710→		}
   711→
   712→		// Note: We don't compute diff stats for uncommitted checkpoints
   713→		// because shadow commits store complete trees and diffing them
   714→		// against their parents gives incorrect (cumulative) results.
   715→
   716→		// Build session info from the rewind point
   717→		var sessions []SessionInfo
   718→		if point.SessionID != "" {
   719→			sessions = append(sessions, SessionInfo{
   720→				SessionID:   point.SessionID,
   721→				Description: point.SessionPrompt,
   722→				IsActive:    isSessionActive(point.SessionID),
   723→				StepsCount:  0, // Not available from rewind point
   724→			})
   725→		}
   726→
   727→		cpInfo := CheckpointInfo{
   728→			CheckpointID:  point.ID, // Use commit hash as ID for uncommitted checkpoints
   729→			CommitHash:    shortHash,
   730→			CommitMsg:     point.Message,
   731→			CreatedAt:     point.Date,
   732→			IsTask:        point.IsTaskCheckpoint,
   733→			ToolUseID:     point.ToolUseID,
   734→			IsUncommitted: true,
   735→			Sessions:      sessions,
   736→		}
   737→
   738→		if point.IsTaskCheckpoint {
   739→			taskCheckpoints = append(taskCheckpoints, cpInfo)
   740→		} else {
   741→			promptCheckpoints = append(promptCheckpoints, cpInfo)
   742→		}
   743→	}
   744→
   745→	// Second pass: nest task checkpoints under their parent prompt checkpoint
   746→	// Task checkpoints belong to the most recent prompt checkpoint in the same session
   747→	// that was created before them
   748→	for i := range promptCheckpoints {
   749→		prompt := &promptCheckpoints[i]
   750→		promptSessionID := ""
   751→		if len(prompt.Sessions) > 0 {
   752→			promptSessionID = prompt.Sessions[0].SessionID
   753→		}
   754→
   755→		// Find task checkpoints that belong to this prompt
   756→		// (same session, created after this prompt but before the next prompt)
   757→		var nextPromptTime time.Time
   758→		// Find the next prompt checkpoint in same session (if any)
   759→		for j := i - 1; j >= 0; j-- { // Go backwards since list is newest-first
   760→			if len(promptCheckpoints[j].Sessions) > 0 &&
   761→				promptCheckpoints[j].Sessions[0].SessionID == promptSessionID {
   762→				nextPromptTime = promptCheckpoints[j].CreatedAt
   763→				break
   764→			}
   765→		}
   766→
   767→		for _, task := range taskCheckpoints {
   768→			taskSessionID := ""
   769→			if len(task.Sessions) > 0 {
   770→				taskSessionID = task.Sessions[0].SessionID
   771→			}
   772→
   773→			// Task belongs to this prompt if:
   774→			// 1. Same session
   775→			// 2. Created after this prompt
   776→			// 3. Created before the next prompt (or no next prompt)
   777→			if taskSessionID == promptSessionID &&
   778→				task.CreatedAt.After(prompt.CreatedAt) &&
   779→				(nextPromptTime.IsZero() || task.CreatedAt.Before(nextPromptTime)) {
   780→				prompt.TaskCheckpoints = append(prompt.TaskCheckpoints, task)
   781→			}
   782→		}
   783→	}
   784→
   785→	return promptCheckpoints
   786→}
