	// Format: prompt [agent badge] [N steps]
	// Build suffix first to calculate available space for prompt

	// Build the suffix (agent badge + step count)
	var suffix string
	if node.Agent != "" {
		suffix = "[" + node.Agent + "]"
	}
	if node.SessionStep > 0 {
		if suffix != "" {
			suffix += " "
		}
		suffix += fmt.Sprintf("(%d steps)", node.SessionStep)
	}

